SELECT *
  FROM (
  	SELECT *
      FROM MEMBER_BOOKS
     WHERE MNO=#{mno}
       AND BNO=#{bno}
       AND MBSTATUS IN ('대여중','배송중','연체')
  )
 WHERE ROWNUM=1

mapper.update:
UPDATE MEMBER_BOOKS
   SET MBSTATUS='반납완료',MBRETURN=SYSDATE
 WHERE MNO=#{mno}
   AND BNO=#{bno}
   AND MBNO=#{mbno}
   AND MBSTATUS IN ('연체','대여중')
